   138  /************************
   139   ***  Internal Types  ***
   140   ************************/
   141
   142  /* These are omnipresent so lets save some typing. */
   143  #define CHAR    MD_CHAR
   144  #define SZ      MD_SIZE
   145  #define OFF     MD_OFFSET
