   147  typedef struct MD_MARK_tag MD_MARK;
   148  typedef struct MD_BLOCK_tag MD_BLOCK;
   149  typedef struct MD_CONTAINER_tag MD_CONTAINER;
   150  typedef struct MD_REF_DEF_tag MD_REF_DEF;
   151
   152
   153  /* During analyzes of inline marks, we need to manage stacks of unresolved
   154   * openers of the given type.
   155   * The stack connects the marks via MD_MARK::next;
   156   */
   157  typedef struct MD_MARKSTACK_tag MD_MARKSTACK;
   158  struct MD_MARKSTACK_tag {
   159      int top;        /* -1 if empty. */
   160  };
