   162  /* Context propagated through all the parsing. */
   163  typedef struct MD_CTX_tag MD_CTX;
   164  struct MD_CTX_tag {
   165      /* Immutable stuff (parameters of md_parse()). */
   166      const CHAR* text;
   167      SZ size;
   168      MD_PARSER parser;
   169      void* userdata;
   170
   171      /* When this is true, it allows some optimizations. */
   172      int doc_ends_with_newline;
   173
   174      /* Helper temporary growing buffer. */
   175      CHAR* buffer;
   176      unsigned alloc_buffer;
   177
   178      /* Reference definitions. */
   179      MD_REF_DEF* ref_defs;
   180      int n_ref_defs;
   181      int alloc_ref_defs;
   182      void** ref_def_hashtable;
   183      int ref_def_hashtable_size;
   184      SZ max_ref_def_output;
